/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void d2d_err_add (D2D_Error_Code code)
{  
  UInt8 ptr = d2d_err.count %D2D_ERR_BUFF_SIZE ;
 
  d2d_err.code[ptr] = code ;

  d2d_err.count++ ;

  d2d_do_err_save = TRUE ;
}

